<template>
<div class="page-stack upgrade-page"><PageHeader index="质量评测" title="聊天实验室" description="脱敏对话隔离重放，隐藏版本盲评。技术通过不代表自然度提升。" /><p v-if="feedback" role="status">{{ feedback }}</p>
<Panel title="1. 整理失败对话"><form class="upgrade-form" @submit.prevent="saveCase"><label>案例标题<input v-model="title" required /></label><label>用途<select v-model="split"><option value="development">开发对照</option><option value="holdout">保留集（不参与调参）</option></select></label><label class="upgrade-wide">脱敏案例 JSON<textarea v-model="caseText" required spellcheck="false" /></label><p>请替换真实昵称、账号、联系方式与凭据，仅保留必要上下文。各候选使用独立快照，不外发消息。</p><details class="upgrade-wide"><summary>预览待保存内容</summary><pre>{{ caseText }}</pre></details><label class="upgrade-wide"><span><input v-model="redacted" type="checkbox" style="width:auto" /> 我已检查并完成脱敏</span></label><button class="button" :disabled="busy || !redacted">保存案例</button></form></Panel>
<Panel title="2. 选择案例与预算"><form class="upgrade-form" @submit.prevent="preview"><label>模型路由<select v-model="provider" required @change="proposal = undefined"><option value="" disabled>选择已配置路由</option><option v-for="entry in index.providers" :key="entry.id" :value="entry.id">{{ entry.id }} · {{ entry.model }}</option></select></label><label>请求预算上限<input v-model.number="budget" type="number" min="1" max="1000" required @input="proposal = undefined" /></label><fieldset class="upgrade-wide"><legend>同一批对照案例</legend><p v-if="!index.cases.length">请先保存案例。</p><label v-for="item in index.cases" :key="item.id"><span><input v-model="selected" type="checkbox" :value="item.id" style="width:auto" @change="proposal = undefined" /> {{ item.title }} · {{ item.split === 'holdout' ? '保留集' : '开发集' }}</span></label></fieldset><button class="button button-quiet" :disabled="busy || !selected.length || !provider">预览运行预算</button></form><div v-if="proposal"><p>模型：{{ proposal.model }} · 请求预算：{{ proposal.request_budget }} · 候选：{{ proposal.candidate_count }}</p><ul><li v-for="warning in proposal.warnings" :key="warning">{{ warning }}</li></ul><p>确认后调用真实模型并产生费用，不发送真实聊天消息。</p><button class="button" :disabled="busy" @click="run">确认预算并运行</button></div></Panel>
<Panel title="3. 盲评"><template #actions><button class="button button-quiet" @click="load">刷新作业</button></template><div class="upgrade-actions"><button v-for="entry in index.jobs" :key="entry.id" class="button button-quiet" @click="openJob(entry.id)">{{ entry.model }} · {{ statusLabel(entry.status) }}</button></div><template v-if="job"><p>{{ statusLabel(job.status) }} · {{ job.progress?.completed ?? 0 }} / {{ job.progress?.total ?? 0 }}</p><button v-if="['queued','running'].includes(job.status)" class="button button-quiet" :disabled="busy" @click="cancel">停止剩余请求</button><article v-for="ballot in job.ballots || []" :key="ballot.id" class="upgrade-card"><h3>对照 {{ ballot.case_id }} <small v-if="job.scored_ballot_ids?.includes(ballot.id)">（已评分）</small></h3><div class="upgrade-candidates"><div v-for="(candidate, i) in ballot.candidates" :key="candidate.id"><h4>候选 {{ i + 1 }}</h4><pre>{{ candidate.text || '无可用回复' }}</pre><label><input v-model="votes[ballot.id]" type="radio" :name="ballot.id" :value="candidate.id" /> 选择此候选</label></div></div><div class="upgrade-actions"><label><input v-model="votes[ballot.id]" type="radio" :name="ballot.id" value="tie" /> 平局</label><label><input v-model="votes[ballot.id]" type="radio" :name="ballot.id" value="both_bad" /> 都很差</label></div><form class="upgrade-form" @submit.prevent="score(ballot.id)"><label v-for="dimension in dimensions" :key="dimension.key">{{ dimension.label }}（1–5）<input v-model.number="ratings[ballot.id]![dimension.key]" type="number" min="1" max="5" required /></label><label class="upgrade-wide">依据与失败原因<textarea v-model="reasons[ballot.id]" /></label><button class="button" :disabled="busy || !votes[ballot.id]">保存本组评分</button></form></article><button class="button button-quiet" :disabled="busy" @click="report">完成评分后揭盲报告</button></template><p v-else>选择作业查看候选；评分前隐藏配置与指标。</p></Panel>
<Panel v-if="reportData" title="对照报告"><p>结合失败案例和人工复核判断退化，样本不足时保持实验配置。</p><dl v-if="reportData.metrics" class="upgrade-facts"><dt>模型请求</dt><dd>{{ (reportData.metrics as Record<string, unknown>).wire_calls }}</dd><dt>总耗时（毫秒）</dt><dd>{{ (reportData.metrics as Record<string, unknown>).elapsed_ms }}</dd><dt>失败候选</dt><dd>{{ (reportData.metrics as Record<string, unknown>).failed_candidates }}</dd></dl><details><summary>查看完整评分与版本结果</summary><pre>{{ JSON.stringify(reportData, null, 2) }}</pre></details></Panel></div>
</template>
<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue';
import { upgrades, type QualityIndex, type QualityJob } from '@/api/upgrades';
import PageHeader from '@vue-app/components/PageHeader.vue';
import Panel from '@vue-app/components/Panel.vue';
import './upgradePages.css';
const index = ref<QualityIndex>({cases:[],jobs:[],providers:[],dimensions:[]});
const title = ref(''), split = ref('development'), caseText = ref(JSON.stringify({surface:'group',pipeline:'normal',persona:'填写测试人格',events:[{kind:'message',user_id:'user_1',sender:'用户甲',text:'填写脱敏对话'}]},null,2));
const redacted = ref(false), busy = ref(false), feedback = ref(''), provider = ref(''), budget = ref(30), selected = ref<string[]>([]);
const proposal = ref<Awaited<ReturnType<typeof upgrades.previewQuality>>>(), job = ref<QualityJob>(), reportData = ref<Record<string,unknown>>();
const votes = reactive<Record<string,string>>({}), reasons = reactive<Record<string,string>>({}), ratings = reactive<Record<string,Record<string,number>>>({});
const dimensions = [{key:'naturalness',label:'自然度'},{key:'persona',label:'人格一致性'},{key:'context',label:'上下文理解'},{key:'relationship',label:'关系连续性'},{key:'factuality',label:'事实准确性'}];
let timer: ReturnType<typeof setTimeout> | undefined; let disposed = false;
const statusLabel = (value: string) => ({queued:'等待运行',running:'运行中',completed:'已完成',failed:'运行失败',cancelled:'已停止',interrupted:'已中断'}[value] || '待检查');
const request = () => ({case_ids:[...selected.value],provider_id:provider.value,request_budget:budget.value});
async function task(fn: () => Promise<void>) { busy.value = true; feedback.value = ''; try { await fn(); } catch { feedback.value = '操作未完成，请检查案例格式、预算和服务状态。全部评分后才能揭盲。'; } finally { busy.value = false; } }
async function load() { await task(async () => { index.value = await upgrades.quality(); }); }
async function saveCase() { await task(async () => { await upgrades.saveCase({title:title.value,split:split.value,case:JSON.parse(caseText.value),redact_confirmed:redacted.value}); redacted.value = false; index.value = await upgrades.quality(); feedback.value = '脱敏案例已保存。'; }); }
async function preview() { await task(async () => { const snapshot = JSON.stringify(request()); const value = await upgrades.previewQuality(request()); if (snapshot !== JSON.stringify(request())) { feedback.value = '参数已变更，请重新预览预算。'; return; } proposal.value = value; }); }
async function run() { if (!proposal.value) return; await task(async () => { const created = await upgrades.startQuality({...request(),confirmed:true}); proposal.value = undefined; index.value = await upgrades.quality(); await openJob(created.id); }); }
async function openJob(id: string) { if (timer) clearTimeout(timer); reportData.value = undefined; try { const result = await upgrades.qualityJob(id); if (disposed) return; for (const ballot of result.ballots || []) ratings[ballot.id] ||= Object.fromEntries(dimensions.map(d => [d.key,3])); job.value = result; if (['queued','running'].includes(result.status)) timer = setTimeout(() => void openJob(id),3000); } catch { feedback.value = '作业读取失败，请刷新重试。'; } }
async function score(ballot: string) { await task(async () => { await upgrades.scoreQuality(job.value!.id,{ballot_id:ballot,winner:votes[ballot],dimensions:ratings[ballot],reason:reasons[ballot] || ''}); job.value!.scored_ballot_ids = [...(job.value!.scored_ballot_ids || []),ballot]; feedback.value = '评分已保存。'; }); }
async function report() { await task(async () => { reportData.value = await upgrades.qualityReport(job.value!.id); }); }
async function cancel() { await task(async () => { await upgrades.cancelQuality(job.value!.id); await openJob(job.value!.id); }); }
onMounted(load); onUnmounted(() => { disposed = true; if (timer) clearTimeout(timer); });
</script>
